insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_42_v1'
from (values
('127.246.d.5',3,'A customer calls upset about a late delivery. Which first response builds a positive relationship?','["Listen, apologize for the delay, and offer a solution", "Ask the customer to call back next week", "Transfer the call without comment", "Explain that delays are never your fault"]'::jsonb,0,'Empathy plus action builds goodwill.','original'),
('127.246.d.5',4,'An internal customer in accounting needs data from sales by Friday. Good public relations skills include:','["Telling them to find it themselves", "Confirming the deadline and keeping them updated on progress", "Sending the data whenever convenient", "Ignoring the request until reminded twice"]'::jsonb,1,'Coworkers are customers too.','original'),
('127.246.d.1.A',3,'A manager is starting a new store-opening project. Which task belongs to the initiating phase?','["Training staff on the new register", "Closing out final invoices", "Defining the project goal and identifying who will sponsor it", "Measuring weekly budget variance"]'::jsonb,2,'Initiation defines purpose and authority.','original'),
('127.246.d.1.A',4,'Which document formally authorizes a project and names the project manager?','["Final lessons-learned log", "Weekly status report", "Inventory count sheet", "Project charter"]'::jsonb,3,'The charter launches a project.','original'),
('127.246.d.1.B',3,'A team lists tasks, assigns owners, and sets due dates for a trade-show booth. This is the:','["Planning phase", "Closing phase", "Monitoring phase", "Initiating phase"]'::jsonb,0,'Planning organizes tasks, time, and people.','original'),
('127.246.d.1.B',4,'Which planning tool shows tasks as bars along a calendar so overlaps are visible?','["Pie chart", "Gantt chart", "Balance sheet", "Org chart"]'::jsonb,1,'Gantt charts schedule tasks over time.','original'),
('127.246.d.1.C',3,'A bakery team starts building the new display counters according to the approved plan. This is the:','["Planning phase", "Closing phase", "Executing phase", "Initiating phase"]'::jsonb,2,'Execution carries out the plan.','original'),
('127.246.d.1.C',4,'During execution, a project manager''s main job is to:','["Wait for the project to end", "Rewrite the project goal daily", "Archive the files", "Coordinate people and resources to complete planned work"]'::jsonb,3,'Execution is about coordinated doing.','original'),
('127.246.d.1.D',3,'Comparing actual spending to the budget each week and correcting overspending is:','["Monitoring and controlling", "Initiating", "Closing", "Brainstorming"]'::jsonb,0,'Controlling compares results to the plan.','original'),
('127.246.d.1.D',4,'A project is two weeks behind schedule. Which action best fits monitoring and controlling?','["Ignoring the delay until the end", "Adjusting the schedule or adding resources to recover time", "Canceling all reports", "Removing the deadline silently"]'::jsonb,1,'Controlling responds to variance.','original'),
('127.246.d.1.E',3,'After delivering a new product line, the team reviews what went well and what to fix next time. This occurs at:','["Project initiation", "Project planning", "Project closure", "Project execution"]'::jsonb,2,'Closing captures lessons learned.','original'),
('127.246.d.1.E',4,'Which is a closing task for a business project?','["Writing the project charter", "Creating the first budget", "Selecting the project name", "Obtaining client sign-off and releasing team members"]'::jsonb,3,'Closure confirms completion.','original'),
('127.246.d.2.A',3,'A manager nods, keeps eye contact, and then restates what an employee said. This shows:','["Active listening", "Multitasking", "Daydreaming", "Interrupting"]'::jsonb,0,'Restating confirms understanding.','original'),
('127.246.d.2.A',4,'Which statement best demonstrates active listening?','["\"I already know what you''ll say.\"", "\"So you''re saying the shipment was missing two boxes, correct?\"", "\"Whatever, send me an email.\"", "\"Hurry up and get to the point.\""]'::jsonb,1,'Paraphrasing checks accuracy.','original'),
('127.246.d.2.B',3,'While interviewing a client, an analyst writes brief notes and later turns them into a report. This is:','["Skipping research", "Guessing results", "Recording information to present a report", "Deleting data"]'::jsonb,2,'Notes feed the final report.','original'),
('127.246.d.2.B',4,'Which note-taking practice best supports an accurate report?','["Avoiding any written notes", "Writing everything from memory later", "Noting only your opinions", "Recording key facts, dates, and source names as you go"]'::jsonb,3,'Details preserve accuracy.','original'),
('127.246.d.2.C',3,'To send the same letter to many customers with each name inserted automatically, use:','["Mail merge", "Page break", "Spell check", "Word count"]'::jsonb,0,'Mail merge personalizes bulk letters.','original'),
('127.246.d.2.C',4,'Which advanced word processing feature lets an editor review suggested edits before accepting them?','["Clip art", "Track changes", "Print preview", "Margins"]'::jsonb,1,'Track changes shows proposed edits.','original'),
('127.246.d.2.D',3,'Coworkers edit one proposal at the same time in a cloud document. This is:','["Typing on paper", "Offline filing", "Online word processing collaboration", "Desktop printing"]'::jsonb,2,'Cloud documents allow shared editing.','original'),
('127.246.d.2.D',4,'A major benefit of sharing a document online instead of emailing copies is:','["Extra storage costs", "More duplicate files", "Slower updates", "Everyone works on a single current version"]'::jsonb,3,'A single version avoids confusion.','original'),
('127.246.d.2.E',3,'A team needs a quick answer from a coworker down the hall who is busy in a meeting. The best channel is probably:','["A short instant message", "A certified mail notice", "A fax", "A formal printed letter"]'::jsonb,0,'Match channel to urgency.','original'),
('127.246.d.2.E',4,'When contacting a customer about a contract change, which channel provides a written record?','["A casual rumor", "Email", "A hallway comment", "A voicemail only"]'::jsonb,1,'Email documents the exchange.','original'),
('127.246.d.2.F',3,'A manager works with employees from many cultures. To communicate well, the manager should:','["Use idioms often", "Assume everyone shares the same customs", "Avoid slang and check that messages are understood", "Speak louder and faster"]'::jsonb,2,'Clarity reduces misunderstanding.','original'),
('127.246.d.2.F',4,'Which approach helps when a language barrier exists on a team?','["Skipping instructions", "Talking only in jokes", "Excluding the team member", "Using plain wording, visuals, and written follow-up"]'::jsonb,3,'Multiple modes aid understanding.','original'),
('127.246.d.2.G',3,'Two coworkers disagree about who handles a task. The best first step is to:','["Discuss the issue calmly and look for a shared solution", "Ignore the problem", "Refuse to talk", "Complain to everyone else"]'::jsonb,0,'Calm talk resolves conflict.','original'),
('127.246.d.2.G',4,'In conflict resolution, a compromise means that:','["The issue is hidden", "Each side gives up something to reach agreement", "Nobody speaks", "One side wins everything"]'::jsonb,1,'Compromise is mutual give and take.','original'),
('127.246.d.3.A',3,'A line graph of monthly sales most clearly shows:','["Employee names", "Parts of a whole", "Trends over time", "Address lists"]'::jsonb,2,'Lines show change.','original'),
('127.246.d.3.A',4,'A manager wants a quick visual summary of key figures for busy executives. The best choice is a:','["Blank form", "Ten-page paragraph", "Raw data dump", "Infographic"]'::jsonb,3,'Infographics condense data.','original'),
('127.246.d.3.B',3,'For reliable data about industry salaries, a researcher should use:','["A government or trade association report", "A social media rumor", "An anonymous comment", "A friend''s guess"]'::jsonb,0,'Authoritative sources are reliable.','original'),
('127.246.d.3.B',4,'Which resource is best for finding recent technical specifications for a machine?','["A joke website", "The manufacturer''s manual or website", "A rumor mill", "An old unrelated textbook"]'::jsonb,1,'Primary sources give accurate specs.','original'),
('127.246.d.3.C',3,'When judging a website''s reliability, you should check:','["How many ads appear", "The page''s font", "The author''s credentials and the date published", "Only the color scheme"]'::jsonb,2,'Credibility depends on author and currency.','original'),
('127.246.d.3.C',4,'Two sources give different sales figures. The better step is to:','["Ignore both", "Average them blindly", "Pick the larger number", "Check which source cites original data"]'::jsonb,3,'Original data increases trust.','original'),
('127.246.d.3.D',3,'Listing the books and websites you used at the end of a report is:','["Referencing sources", "Editing the font", "Padding the report", "Printing the cover"]'::jsonb,0,'References credit sources.','original'),
('127.246.d.3.D',4,'Using someone else''s wording without credit is:','["Editing", "Plagiarism", "Proofreading", "Paraphrasing correctly"]'::jsonb,1,'Always credit sources.','original'),
('127.246.d.4.A',3,'Before presenting to the sales team, a manager writes down the main purpose, such as to inform or to persuade. This is:','["Printing handouts", "Skipping planning", "Preparing an oral presentation for a specific purpose", "Reading a script aloud only"]'::jsonb,2,'Purpose shapes content.','original'),
('127.246.d.4.A',4,'A presentation meant to convince executives to fund a project has the purpose to:','["Apologize", "Confuse", "Entertain only", "Persuade"]'::jsonb,3,'Persuasive talks seek approval.','original'),
('127.246.d.4.B',3,'A speaker decides that a chart and a short video would help explain quarterly results. This is:','["Identifying support materials", "Deleting slides", "Skipping visuals", "Hiding data"]'::jsonb,0,'Choosing aids comes first.','original'),
('127.246.d.4.B',4,'Which support material best shows how a product assembly works step by step?','["A spreadsheet of salaries", "A demonstration video", "A long paragraph of text", "A blank slide"]'::jsonb,1,'Visuals clarify processes.','original'),
('127.246.d.4.C',3,'A presenter designs slides with large fonts and simple charts. This is:','["Ignoring the audience", "Closing the project", "Preparing support materials", "Delivering the talk"]'::jsonb,2,'Preparing aids supports delivery.','original'),
('127.246.d.4.C',4,'A well-prepared handout should:','["Repeat every word of the talk", "Contain only logos", "Be left blank", "Summarize key points and contact information"]'::jsonb,3,'Handouts reinforce the message.','original'),
('127.246.d.4.D',3,'A speaker keeps eye contact, varies voice tone, and uses a story to keep listeners interested. This is:','["Sustaining listeners'' attention", "Speaking in monotone", "Facing the screen", "Reading a script"]'::jsonb,0,'Engagement holds attention.','original'),
('127.246.d.4.D',4,'Which action is most likely to lose an audience?','["Pausing for emphasis", "Reading dense slides word for word", "Asking a relevant question", "Using an example"]'::jsonb,1,'Reading slides disengages listeners.','original'),
('127.246.d.4.E',3,'A talk to new interns should differ from one to the board of directors in:','["The room temperature", "The presenter''s shoes", "Vocabulary and level of detail", "The speaker''s name"]'::jsonb,2,'Audience determines depth.','original'),
('127.246.d.4.E',4,'Presenting to a group unfamiliar with industry jargon, the speaker should:','["Use more acronyms", "Skip the explanation", "Speak faster", "Define terms and use plain examples"]'::jsonb,3,'Adapt wording to the audience.','original'),
('127.246.d.4.F',3,'Adding audio, video clips, and animation to a product demo is using:','["Multimedia strategies", "Silence", "A paper memo", "Plain text only"]'::jsonb,0,'Multimedia engages several senses.','original'),
('127.246.d.4.F',4,'A good multimedia practice is to:','["Add unrelated clips", "Use media that supports the message without distracting", "Play loud music throughout", "Fill slides with effects"]'::jsonb,1,'Media must serve the purpose.','original'),
('127.246.d.4.G',3,'Sharing a slide deck by link so remote coworkers can comment is using:','["Index cards", "Overhead transparencies", "Online presentation management technology", "Paper flip charts"]'::jsonb,2,'Cloud tools support remote work.','original'),
('127.246.d.4.G',4,'Which feature of an online presentation tool helps a distributed team?','["Hidden version history", "Printing only", "Fixed single user", "Shared editing and commenting"]'::jsonb,3,'Collaboration needs shared access.','original'),
('127.246.d.6.A',3,'A spreadsheet that finds a product''s price by entering its item number uses a:','["Lookup table", "Pie chart", "Header image", "Macro-free label"]'::jsonb,0,'Lookups return matching data.','original'),
('127.246.d.6.A',4,'A what-if analysis answers the question:','["When is lunch?", "How would profit change if sales fell 10 percent?", "Who is the CEO?", "What is the office address?"]'::jsonb,1,'What-if tests scenarios.','original'),
('127.246.d.6.B',3,'An income statement compared across two years shows how:','["Fonts were set", "Employees were hired", "Revenue and expenses changed", "Colors were chosen"]'::jsonb,2,'Comparisons show change.','original'),
('127.246.d.6.B',4,'A projected financial statement estimates:','["Office layout", "Past events only", "Employee birthdays", "Future income and expenses"]'::jsonb,3,'Projections look forward.','original'),
('127.246.d.7.A',3,'A company wants a database to track customers, orders, and products. The designer should first:','["Identify the data and how tables relate", "Buy a new printer", "Write the annual report", "Choose a logo"]'::jsonb,0,'Design starts with requirements.','original'),
('127.246.d.7.A',4,'Storing each customer''s data once and linking it to orders avoids:','["All queries", "Duplicate and inconsistent data", "Primary keys", "Any reports"]'::jsonb,1,'Normalization reduces redundancy.','original'),
('127.246.d.7.B',3,'A query that changes all prices by 5 percent at once is a(n):','["Print query", "Delete report", "Update query", "Make-up form"]'::jsonb,2,'Update queries modify records.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_42_v1'
from (values
('127.246.d.7.B',4,'To combine data from a Customers table and an Orders table, an advanced query uses a:','["Footnote", "Template", "Border", "Join"]'::jsonb,3,'Joins link tables.','original'),
('127.246.d.8.B',3,'A student presents an electronic portfolio to a panel of local business owners. This is:','["Presenting the portfolio to stakeholders", "Hiding the portfolio", "Deleting work", "Printing a flyer"]'::jsonb,0,'Stakeholders review results.','original'),
('127.246.d.8.B',4,'When presenting a portfolio, a student should:','["Read every page silently", "Explain how each item shows skills and growth", "Avoid questions", "Skip the strongest work"]'::jsonb,1,'Connect evidence to skills.','original'),
('127.246.d.8.A.i',3,'A portfolio section that lists skills you mastered in your course shows:','["Your hobbies only", "Your lunch order", "Attainment of technical skill competencies", "Your favorite music"]'::jsonb,2,'Competencies show ability.','original'),
('127.246.d.8.A.i',4,'Which is the best evidence of a technical skill in a portfolio?','["A rumor", "A guess", "A vague claim", "A dated skills checklist signed by an instructor"]'::jsonb,3,'Verified evidence is credible.','original'),
('127.246.d.8.A.ii',3,'Including a copy of an industry credential in a portfolio shows:','["Licensures or certifications", "Social events", "Class schedules", "Weekend plans"]'::jsonb,0,'Credentials prove qualification.','original'),
('127.246.d.8.A.ii',4,'A certification belongs in a portfolio because it:','["Replaces a resume", "Verifies that you met a recognized standard", "Costs nothing", "Shows your age"]'::jsonb,1,'Certification is third-party proof.','original'),
('127.246.d.8.A.iii',3,'A letter noting a student''s scholarship belongs in the portfolio section for:','["Budgets", "References", "Recognitions, awards, and scholarships", "Work samples"]'::jsonb,2,'Honors show achievement.','original'),
('127.246.d.8.A.iii',4,'An employer sees an award for top sales student. This most likely signals:','["A lack of effort", "Poor attendance", "Unreliability", "Achievement and motivation"]'::jsonb,3,'Awards reflect accomplishment.','original'),
('127.246.d.8.A.iv',3,'Volunteering at a food bank and serving as a club officer would be listed under:','["Extended learning experiences", "Letters of application", "Work samples only", "Technical skill tests"]'::jsonb,0,'Service shows involvement.','original'),
('127.246.d.8.A.iv',4,'Active participation in a career and technical student organization shows:','["Only social time", "Leadership and commitment outside class", "Absence from school", "A lack of interest"]'::jsonb,1,'CTSO participation builds skills.','original'),
('127.246.d.8.A.v',3,'A sample letter of application should be tailored to:','["No one", "A friend", "A specific job and employer", "Any reader"]'::jsonb,2,'Tailoring improves impact.','original'),
('127.246.d.8.A.v',4,'A strong application letter opens by:','["Listing only hobbies", "Asking about vacation time", "Complaining about past jobs", "Stating the position you want and why you qualify"]'::jsonb,3,'Lead with purpose.','original'),
('127.246.d.8.A.vi',3,'A short summary of your major accomplishments in a portfolio is a(n):','["Abstract of key points", "Contract", "Invoice", "Budget"]'::jsonb,0,'Abstracts condense highlights.','original'),
('127.246.d.8.A.vi',4,'A good abstract of accomplishments is:','["Several pages long", "Brief and focused on results", "Full of unrelated details", "Blank"]'::jsonb,1,'Concise summaries are useful.','original'),
('127.246.d.8.A.vii',3,'A resume in a portfolio should list education, skills, and:','["Passwords", "Medical history", "Work experience", "Favorite foods"]'::jsonb,2,'Experience is a core resume section.','original'),
('127.246.d.8.A.vii',4,'Which resume feature is most effective?','["Irrelevant details", "Typos for personality", "Long paragraphs", "Accurate content with action verbs and no errors"]'::jsonb,3,'Accuracy and clarity matter.','original'),
('127.246.d.8.A.viii',3,'A report you wrote for class, placed in a portfolio, is a:','["Sample of work", "Time card", "Reference letter", "Application form"]'::jsonb,0,'Samples demonstrate ability.','original'),
('127.246.d.8.A.viii',4,'When choosing work samples, include those that:','["Are oldest", "Best show the skills the audience values", "Are least complete", "Are unrelated"]'::jsonb,1,'Match samples to purpose.','original'),
('127.246.d.8.A.ix',3,'A written review from your teacher about your performance is a(n):','["Budget", "Resume", "Evaluation", "Invoice"]'::jsonb,2,'Evaluations give outside feedback.','original'),
('127.246.d.8.A.ix',4,'A teacher''s evaluation helps an employer see:','["Your favorite song", "Your age", "Your home address", "Your work habits and skills from an observer"]'::jsonb,3,'Third-party views add credibility.','original'),
('127.247.d.1.A',3,'Getting work done through people and other resources to reach goals is called:','["Management", "Retailing", "Banking", "Marketing"]'::jsonb,0,'Management coordinates resources toward goals.','original'),
('127.247.d.1.A',4,'Which best defines management?','["Owning real estate", "Coordinating people and resources to achieve organizational goals", "Selling products directly", "Printing documents"]'::jsonb,1,'Management is goal-directed coordination.','original'),
('127.247.d.1.B',3,'Setting objectives is part of which management function?','["Controlling", "Staffing", "Planning", "Directing"]'::jsonb,2,'Planning sets goals.','original'),
('127.247.d.1.B',4,'A manager hires, trains, and schedules employees. This is the function of:','["Organizing equipment only", "Planning", "Controlling", "Staffing"]'::jsonb,3,'Staffing fills roles with people.','original'),
('127.247.d.1.C',3,'In the management pyramid, top managers focus on:','["Long-term strategy", "Individual shifts", "Cleaning schedules", "Daily tasks"]'::jsonb,0,'Top managers set direction.','original'),
('127.247.d.1.C',4,'The management level that directly supervises workers is:','["Chief executive", "First-line management", "Board of directors", "Top management"]'::jsonb,1,'First-line managers oversee employees.','original'),
('127.247.d.1.D',3,'The role of a manager who negotiates with suppliers is that of a:','["Janitor", "Cashier", "Negotiator", "Driver"]'::jsonb,2,'Managers play several roles.','original'),
('127.247.d.1.D',4,'A manager who explains company news to employees acts as a:','["Competitor", "Auditor only", "Customer", "Spokesperson or communicator"]'::jsonb,3,'Managers communicate.','original'),
('127.247.d.1.E',3,'The early idea that workers could be made more efficient by studying tasks is called:','["Scientific management", "Ecology", "Totalitarian rule", "Social media"]'::jsonb,0,'Taylor''s scientific management studied efficiency.','original'),
('127.247.d.1.E',4,'The human relations approach to management stresses:','["Strict rules only", "Employee needs and social relationships", "Ignoring morale", "Machines only"]'::jsonb,1,'It values people.','original'),
('127.247.d.1.F',3,'A change in government regulations is an example of an:','["Office layout", "Internal policy", "External factor", "Employee habit"]'::jsonb,2,'Regulations come from outside.','original'),
('127.247.d.1.F',4,'Company culture and employee skills are examples of:','["External laws", "Competitors'' ads", "Weather", "Internal environmental factors"]'::jsonb,3,'Culture is internal.','original'),
('127.247.d.1.G',3,'Telling the truth in reports and treating coworkers fairly is:','["Ethical workplace behavior", "Rule breaking", "Lying", "Favoritism"]'::jsonb,0,'Ethics means honest, fair conduct.','original'),
('127.247.d.1.G',4,'A worker reports an accounting error that benefits the company. This is:','["Illegal", "Ethical behavior", "Unethical behavior", "Irrelevant"]'::jsonb,1,'Honesty even when costly.','original'),
('127.247.d.1.H',3,'When facing an ethical decision, a good first step is to:','["Act immediately", "Ignore rules", "Gather the facts and identify who is affected", "Ask no one"]'::jsonb,2,'Fact-finding precedes choice.','original'),
('127.247.d.1.H',4,'Which question helps test an ethical decision?','["Will nobody notice?", "Will it be cheap?", "Is it quick?", "Would I be comfortable if everyone knew about it?"]'::jsonb,3,'Transparency tests ethics.','original'),
('127.247.d.1.I',3,'A firm that reduces pollution beyond what the law requires shows:','["Social responsibility", "Competition", "Overhead", "Tax avoidance"]'::jsonb,0,'Responsibility goes beyond profit.','original'),
('127.247.d.1.I',4,'Social responsibility means a business considers its effects on:','["Only competitors", "Society and the environment as well as profit", "Only owners", "Only profits"]'::jsonb,1,'Stakeholders extend beyond owners.','original'),
('127.247.d.1.J',3,'A recycling program started by management shows how a socially responsible policy can be:','["Random", "Illegal", "Initiated and carried out by leaders", "Ignored"]'::jsonb,2,'Policies begin with leadership.','original'),
('127.247.d.1.J',4,'For a socially responsible policy to work, managers must:','["Skip training", "Avoid reports", "Keep it secret", "Communicate it and measure results"]'::jsonb,3,'Implementation needs follow-through.','original'),
('127.247.d.1.K',3,'Studying a real company''s scandal to learn from it is:','["Researching a contemporary ethics case", "Inventory control", "Advertising", "Gossip"]'::jsonb,0,'Case studies teach lessons.','original'),
('127.247.d.1.K',4,'The best way to research an ethics case is to:','["Rely on rumors", "Use news reports and company statements from reliable sources", "Use one anonymous post", "Guess the outcome"]'::jsonb,1,'Reliable sources support analysis.','original'),
('127.247.d.2.A',3,'Deciding in advance what an organization will do and how is:','["Disciplining", "Controlling", "Planning", "Staffing"]'::jsonb,2,'Planning prepares the way.','original'),
('127.247.d.2.A',4,'Planning is best described as:','["Choosing a logo", "Reviewing last year''s mistakes only", "Filing papers", "Setting goals and deciding how to reach them"]'::jsonb,3,'Planning sets goals and means.','original'),
('127.247.d.2.B',3,'A restaurant that opens without any plan for food costs may:','["Run out of money", "Pay no taxes", "Have no customers ever", "Always profit"]'::jsonb,0,'Planning guards against waste.','original'),
('127.247.d.2.B',4,'Proper planning helps managers:','["Skip decisions", "Use resources efficiently and prepare for change", "Avoid goals", "Increase confusion"]'::jsonb,1,'Plans guide action.','original'),
('127.247.d.2.C',3,'A plan for how a company will raise and spend money is a(n):','["Marketing plan", "Staffing chart", "Financial plan", "Safety drill"]'::jsonb,2,'Financial plans cover funds.','original'),
('127.247.d.2.C',4,'A plan for promoting a new product to customers is a(n):','["Inventory log", "Production line", "Financial audit", "Marketing plan"]'::jsonb,3,'Marketing plans address promotion.','original'),
('127.247.d.2.E',3,'A company that makes a product cheaper or better than rivals has a:','["Competitive advantage", "Liability", "Tax", "Deficit"]'::jsonb,0,'Advantage separates it from rivals.','original'),
('127.247.d.2.E',4,'Which is a source of competitive advantage?','["Unclear goals", "A patented process that lowers costs", "Poor service", "Outdated tools"]'::jsonb,1,'Unique strengths create advantage.','original'),
('127.247.d.2.F',3,'A firm decides to be the lowest-cost producer in its market. This is its:','["Holiday schedule", "Dress code", "Organizational strategy", "Fire drill"]'::jsonb,2,'Strategy is the overall approach.','original'),
('127.247.d.2.F',4,'A strategy is different from a daily task because it:','["Has no goal", "Applies to one hour", "Is always secret", "Guides long-term direction"]'::jsonb,3,'Strategy is long-range.','original'),
('127.247.d.2.G',3,'A company that develops a new product no rival offers is using:','["Innovative strategy", "Delay", "Shutdown", "Imitation"]'::jsonb,0,'Innovation creates new value.','original'),
('127.247.d.2.G',4,'To encourage innovation, a manager can:','["Punish every mistake", "Reward new ideas and allow reasonable risk", "Freeze all budgets", "Ban suggestions"]'::jsonb,1,'Culture supports innovation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
