insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_42_v1'
from (values
('127.247.d.2.H',3,'Falling sales for three quarters may signal the:','["End of competition", "Need to ignore the data", "Need for change", "Perfect plan"]'::jsonb,2,'Declining results call for change.','original'),
('127.247.d.2.H',4,'Which is a sign that an organization needs to change?','["Customers praise it", "Profits rise steadily", "Costs are falling", "New technology is making its methods obsolete"]'::jsonb,3,'Obsolescence demands change.','original'),
('127.247.d.2.I',3,'Managing business operations across several countries is called:','["Global management", "Local management", "Home management", "Remote control"]'::jsonb,0,'Global management crosses borders.','original'),
('127.247.d.2.I',4,'A manager of a company with factories on three continents practices:','["Departmental review", "Global management", "Local sales only", "Domestic planning only"]'::jsonb,1,'Multi-country operations need global management.','original'),
('127.247.d.2.J',3,'A company expanding abroad must consider differences in:','["Only logo color", "Only time of day", "Laws, language, and customs", "Only paper size"]'::jsonb,2,'Global operations require cultural awareness.','original'),
('127.247.d.2.J',4,'To function well in a global environment, an organization should:','["Ignore foreign rules", "Use the same approach everywhere", "Avoid translation", "Adapt products and practices to local markets"]'::jsonb,3,'Adaptation improves success.','original'),
('127.247.d.2.D.i',3,'The first step in management decision making is:','["Identifying the problem", "Choosing an alternative", "Implementing a choice", "Evaluating the outcome"]'::jsonb,0,'A problem must be defined first.','original'),
('127.247.d.2.D.i',4,'A manager notes that returns have doubled. The first decision step is to:','["Fire someone", "Define what the problem really is", "Order more stock", "Change the logo"]'::jsonb,1,'Define before acting.','original'),
('127.247.d.2.D.ii',3,'After the problem is identified, managers next:','["Celebrate", "Evaluate results", "Gather information", "Skip analysis"]'::jsonb,2,'Facts support choices.','original'),
('127.247.d.2.D.ii',4,'Which source gives managers facts for a decision?','["Guesses", "Wishes", "Rumors", "Sales reports and customer surveys"]'::jsonb,3,'Data informs decisions.','original'),
('127.247.d.2.D.iii',3,'Brainstorming several possible solutions is:','["Developing alternatives", "Evaluating the decision", "Collecting data", "Closing the project"]'::jsonb,0,'Alternatives widen options.','original'),
('127.247.d.2.D.iii',4,'Why develop more than one alternative?','["To avoid action", "To compare options before choosing", "To confuse staff", "To delay forever"]'::jsonb,1,'Choices need comparison.','original'),
('127.247.d.2.D.iv',3,'Weighing the costs and benefits of each option is:','["Closing", "Implementing", "Evaluating alternatives", "Identifying the problem"]'::jsonb,2,'Evaluation compares options.','original'),
('127.247.d.2.D.iv',4,'Which criterion is useful when evaluating alternatives?','["Length of the memo", "The font used", "Color of the folder", "Cost, risk, and fit with goals"]'::jsonb,3,'Criteria guide evaluation.','original'),
('127.247.d.2.D.v',3,'Selecting the best solution after comparison is:','["Choosing an alternative", "Identifying the problem", "Closing the files", "Gathering facts"]'::jsonb,0,'The decision itself is the choice.','original'),
('127.247.d.2.D.v',4,'A manager picks the supplier with the best quality-to-price ratio. This is:','["Starting over", "Choosing an alternative", "Defining a problem", "Evaluating the result"]'::jsonb,1,'Selection follows evaluation.','original'),
('127.247.d.2.D.vi',3,'Putting the chosen solution into action is:','["Gathering information", "Brainstorming", "Implementing the decision", "Identifying the problem"]'::jsonb,2,'Implementation acts on the choice.','original'),
('127.247.d.2.D.vi',4,'For smooth implementation, a manager should:','["Skip training", "Keep it secret", "Change it daily", "Communicate the plan and assign responsibilities"]'::jsonb,3,'Clear roles help execution.','original'),
('127.247.d.2.D.vii',3,'Checking whether the decision solved the problem is:','["Evaluating the decision", "Identifying the problem", "Hiring", "Brainstorming"]'::jsonb,0,'Evaluation closes the loop.','original'),
('127.247.d.2.D.vii',4,'If a decision did not work, the manager should:','["Ignore the outcome", "Learn from results and adjust", "Repeat it unchanged", "Blame others"]'::jsonb,1,'Feedback improves future choices.','original'),
('127.247.d.3.A',3,'An adaptive organization can:','["Never change", "Ignore customers", "Change quickly when conditions change", "Resist all new ideas"]'::jsonb,2,'Adaptive structures respond.','original'),
('127.247.d.3.A',4,'To design an adaptive organization, managers might:','["Avoid feedback", "Add many layers", "Forbid cross-training", "Use flexible teams and short chains of communication"]'::jsonb,3,'Flexibility aids adaptation.','original'),
('127.247.d.3.B',3,'Grouping employees by function, such as sales or accounting, is a type of:','["Departmentalization", "Decentralization", "Delegation", "Motivation"]'::jsonb,0,'Departments group jobs.','original'),
('127.247.d.3.B',4,'A company grouped by product line, with a team for each, uses:','["Functional grouping", "Product departmentalization", "No structure", "Geographic grouping"]'::jsonb,1,'Grouping follows products.','original'),
('127.247.d.3.C',3,'The line of authority from top to bottom in an organization is the:','["Price list", "Time clock", "Chain of command", "Break room"]'::jsonb,2,'The chain shows who reports to whom.','original'),
('127.247.d.3.C',4,'An employee takes a concern to the direct supervisor first because of the:','["Parking policy", "Pay scale", "Dress code", "Chain of command"]'::jsonb,3,'Follow the reporting line.','original'),
('127.247.d.3.D',3,'A store manager directing cashiers who report to him uses:','["Line authority", "No authority", "Staff advice only", "Peer review"]'::jsonb,0,'Line authority is direct supervision.','original'),
('127.247.d.3.D',4,'Line authority gives a manager the right to:','["Audit only", "Direct subordinates'' work", "Only observe", "Advise only"]'::jsonb,1,'Line managers direct.','original'),
('127.247.d.3.E',3,'A human resources specialist who advises managers but cannot order their employees has:','["Line authority", "No role", "Staff authority", "Final authority"]'::jsonb,2,'Staff positions support and advise.','original'),
('127.247.d.3.E',4,'Staff authority is mainly:','["Directing sales teams", "Ordering production", "Controlling a line", "Advisory and supportive"]'::jsonb,3,'Staff supports line functions.','original'),
('127.247.d.3.F',3,'A tall organizational structure with many levels may slow:','["Communication and decisions", "Reporting lines", "Pay", "Supervision"]'::jsonb,0,'More levels slow information.','original'),
('127.247.d.3.F',4,'A flat structure has the advantage of:','["Slower decisions", "Faster communication but wider supervision", "More managers", "Longer chains"]'::jsonb,1,'Fewer levels speed communication.','original'),
('127.247.d.3.G',3,'A manager who assigns a task to an employee along with the authority to do it is:','["Auditing", "Hoarding work", "Delegating", "Firing"]'::jsonb,2,'Delegation shares work and authority.','original'),
('127.247.d.3.G',4,'Effective delegation requires the manager to:','["Hide expectations", "Provide no authority", "Do the task anyway", "Give clear instructions and the needed authority"]'::jsonb,3,'Delegation needs clarity.','original'),
('127.247.d.3.H',3,'In a decentralized organization, decisions are made:','["By lower-level managers close to the work", "By customers only", "By no one", "Only by top executives"]'::jsonb,0,'Authority is spread out.','original'),
('127.247.d.3.H',4,'A centralized organization is characterized by:','["Team-run decisions", "Decision making concentrated at the top", "No leadership", "Wide employee autonomy"]'::jsonb,1,'Centralization concentrates authority.','original'),
('127.247.d.3.I',3,'A group of employees with complementary skills working toward a shared goal is a:','["Customer base", "Audience", "Team", "Crowd"]'::jsonb,2,'Teams share goals.','original'),
('127.247.d.3.I',4,'Teamwork is most effective when members:','["Avoid roles", "Work in secret", "Compete for credit", "Share goals and communicate openly"]'::jsonb,3,'Collaboration needs communication.','original'),
('127.247.d.3.J',3,'The number of employees a manager directly supervises is the:','["Span of control", "Pay grade", "Chain of command", "Job title"]'::jsonb,0,'Span of control counts direct reports.','original'),
('127.247.d.3.J',4,'A manager with a very wide span of control may find it hard to:','["Reduce costs", "Give each employee close attention", "Communicate by email", "Delegate tasks"]'::jsonb,1,'Wide spans reduce supervision time.','original'),
('127.247.d.4.A',3,'Hiring based on a candidate''s qualifications rather than personal favoritism is:','["Unethical", "Unnecessary", "An ethical HR practice", "Illegal in all cases"]'::jsonb,2,'Ethics in HR means fairness.','original'),
('127.247.d.4.A',4,'Keeping employee records private is an example of:','["A marketing tool", "A sales tactic", "A cost cut", "Ethics in human resource management"]'::jsonb,3,'Confidentiality is ethical.','original'),
('127.247.d.4.B',3,'A federal law that prohibits employment discrimination on the basis of race, color, religion, sex, or national origin is:','["Title VII of the Civil Rights Act", "The Clean Air Act", "The Tax Code", "The Sherman Act"]'::jsonb,0,'Title VII bars such discrimination.','original'),
('127.247.d.4.B',4,'The Americans with Disabilities Act requires employers to:','["Ignore disabilities", "Provide reasonable accommodations for qualified workers", "Hire only certain applicants", "Reduce pay"]'::jsonb,1,'The ADA requires accommodations.','original'),
('127.247.d.4.C',3,'A hiring practice that seems neutral but disproportionately excludes a protected group has:','["No effect", "Good faith", "Adverse impact", "Positive impact"]'::jsonb,2,'Adverse impact harms a group.','original'),
('127.247.d.4.C',4,'Refusing to promote a worker solely because of age is:','["A legal rule", "A training method", "Fair practice", "Employment discrimination"]'::jsonb,3,'Age discrimination is illegal.','original'),
('127.247.d.4.D',3,'Repeated unwelcome comments of a sexual nature at work are:','["Sexual harassment", "Training", "Teamwork", "Friendly talk"]'::jsonb,0,'Unwelcome conduct is harassment.','original'),
('127.247.d.4.D',4,'An employee who experiences harassment should:','["Retaliate", "Report it to a supervisor or HR", "Quit immediately without telling", "Stay silent"]'::jsonb,1,'Reporting starts correction.','original'),
('127.247.d.4.E',3,'Posting a job opening on a company website is a method of:','["Auditing", "Training", "Recruiting", "Terminating"]'::jsonb,2,'Posting attracts applicants.','original'),
('127.247.d.4.E',4,'Recruiting from within the company is called:','["Layoff", "Outsourcing", "External recruiting", "Internal recruiting"]'::jsonb,3,'Internal recruiting uses current staff.','original'),
('127.247.d.4.F',3,'Reviewing applications, interviewing, and checking references is the:','["Selection process", "Training process", "Payroll process", "Termination process"]'::jsonb,0,'Selection chooses the best candidate.','original'),
('127.247.d.4.F',4,'A structured interview asks every candidate:','["Random personal questions", "The same job-related questions", "Only about hobbies", "Different questions"]'::jsonb,1,'Consistency improves fairness.','original'),
('127.247.d.4.G',3,'A new employee''s first-week orientation is an example of:','["A promotion", "An audit", "Training for newly hired employees", "A layoff"]'::jsonb,2,'Orientation introduces the job.','original'),
('127.247.d.4.G',4,'On-the-job training means learning by:','["Watching videos only", "Waiting", "Reading only", "Doing the work with guidance"]'::jsonb,3,'OJT is hands-on.','original'),
('127.247.d.4.H',3,'Sending a current employee to a workshop to learn new skills is:','["Professional development", "Recruiting", "Discipline", "A layoff"]'::jsonb,0,'Development builds skills.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
